-- GEOLYTIX UK Retail Points v49 (2026-09), Open Data CC0 1.0.
-- https://geolytix.com/blog/supermarket-retail-points/
-- Generated from geolytix_retailpoints_v49_202609.csv. The BNG and WGS84 coordinate columns are stored as the geom_p_4326 point.
-- Invalid open_date values in the source, eg. 20240699, are null.

CREATE SCHEMA IF NOT EXISTS geodata;

CREATE TABLE geodata.uk_glx_open_retail_points (
  id BIGINT PRIMARY KEY,
  retailer TEXT,
  fascia TEXT,
  store_name TEXT,
  add_one TEXT,
  add_two TEXT,
  town TEXT,
  suburb TEXT,
  postcode TEXT,
  pqi TEXT,
  size_band TEXT,
  county TEXT,
  open_date DATE,
  geom_p_4326 GEOMETRY(Point, 4326)
);


CREATE INDEX uk_glx_open_retail_points_geom_idx ON geodata.uk_glx_open_retail_points USING GIST (geom_p_4326);
